"""
views/vm_config_dialog.py

Dialog for editing a VM's configuration post-creation.

Changes that require the VM to be stopped (vCPUs, memory) are disabled
with a clear explanation when the VM is running.

All other changes (network, ISO, boot order, SPICE) are applied via
libvirt defineXML which accepts persistent redefinition of running
domains — changes take effect after the next boot.

The SPICE section is hidden for headless VMs (sys-net, sys-firewall)
that have no graphics device.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib

from ..backend.libvirt_manager import LibvirtManager, DomainInfo
from .vm_create_dialog import _make_file_chooser_button

_DEFAULT_NETWORKS = ["bulwark-appvms", "bulwark-internal", "default"]
_SPICE_ADDRESSES  = ["127.0.0.1", "0.0.0.0"]
_SPICE_LABELS     = ["Localhost only (recommended)", "All interfaces"]


class VMConfigDialog(Adw.Dialog):
    def __init__(self, manager: LibvirtManager, info: DomainInfo):
        super().__init__()
        self._mgr     = manager
        self._info    = info
        self._running = info.is_running

        self.set_title(f"Configure — {info.meta.get('label', info.name)}")
        self.set_content_width(520)
        self.set_content_height(680)

        toolbar = Adw.ToolbarView()
        self.set_child(toolbar)

        header = Adw.HeaderBar()
        btn_close = Gtk.Button(label="Close")
        btn_close.connect("clicked", lambda _: self.close())
        header.pack_start(btn_close)

        btn_apply = Gtk.Button(label="Apply")
        btn_apply.add_css_class("suggested-action")
        btn_apply.connect("clicked", self._on_apply)
        header.pack_end(btn_apply)
        toolbar.add_top_bar(header)

        clamp = Adw.Clamp()
        clamp.set_maximum_size(480)
        clamp.set_margin_top(16)
        clamp.set_margin_bottom(16)
        clamp.set_margin_start(16)
        clamp.set_margin_end(16)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(clamp)
        toolbar.set_content(scroll)

        body = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
        clamp.set_child(body)

        # Status / error banner
        self._banner = Adw.Banner()
        self._banner.set_revealed(False)
        body.append(self._banner)

        # Running info banner — only for vCPU/memory context
        if self._running:
            warn = Adw.Banner()
            warn.set_title(
                "VM is running. vCPU and memory changes require a stop. "
                "Network, boot, and ISO changes apply on next boot."
            )
            warn.set_revealed(True)
            body.append(warn)

        # Fetch current config from XML
        cfg = manager.get_vm_config_summary(info.name)
        has_spice = cfg.get("has_spice", False)

        # ── Hardware ──────────────────────────────────────────────────────
        hw_group = Adw.PreferencesGroup()
        hw_group.set_title("Hardware")
        if self._running:
            hw_group.set_description("Requires VM to be stopped.")
        body.append(hw_group)

        self._vcpu_row = Adw.SpinRow.new_with_range(1, 32, 1)
        self._vcpu_row.set_title("vCPUs")
        self._vcpu_row.set_value(cfg.get("vcpus", 2))
        self._vcpu_row.set_sensitive(not self._running)
        hw_group.add(self._vcpu_row)

        self._mem_row = Adw.SpinRow.new_with_range(256, 131072, 256)
        self._mem_row.set_title("Memory (MB)")
        self._mem_row.set_value(cfg.get("memory_mb", 2048))
        self._mem_row.set_sensitive(not self._running)
        hw_group.add(self._mem_row)

        # ── Network — one row per interface ──────────────────────────────
        net_group = Adw.PreferencesGroup()
        net_group.set_title("Network")
        if self._running:
            net_group.set_description("Changes take effect after next boot.")
        body.append(net_group)

        # _net_combos: list of (iface_index, combo_widget, options_list)
        self._net_combos: list[tuple[int, Adw.ComboRow, list[str]]] = []

        networks = cfg.get("networks", [])
        if not networks:
            empty_row = Adw.ActionRow()
            empty_row.set_title("No network interfaces")
            empty_row.set_subtitle("This VM has no virtual network interfaces defined.")
            net_group.add(empty_row)
        else:
            for iface in networks:
                iface_idx    = iface["index"]
                current_net  = iface["source"]
                alias        = iface["alias"]
                mac          = iface["mac"]

                # Build options list — include current value if not in defaults
                net_options = list(_DEFAULT_NETWORKS)
                if current_net and current_net not in net_options:
                    net_options.insert(0, current_net)

                combo = Adw.ComboRow()
                # Label: alias if informative (not just "net0"), plus MAC
                label = alias if not alias.startswith("net") else f"Interface {iface_idx}"
                combo.set_title(label)
                if mac:
                    combo.set_subtitle(mac)

                model = Gtk.StringList()
                for n in net_options:
                    model.append(n)
                combo.set_model(model)

                try:
                    sel_idx = net_options.index(current_net)
                except ValueError:
                    sel_idx = 0
                combo.set_selected(sel_idx)

                net_group.add(combo)
                self._net_combos.append((iface_idx, combo, net_options))

        # ── Display / SPICE ───────────────────────────────────────────────
        # Hidden entirely for headless VMs (sys-net, sys-firewall)
        self._display_group = Adw.PreferencesGroup()
        self._display_group.set_title("Display")
        if self._running:
            self._display_group.set_description("Change takes effect after next boot.")
        body.append(self._display_group)

        if has_spice:
            # SPICE listen address picker
            self._spice_row = Adw.ComboRow()
            self._spice_row.set_title("SPICE listen address")
            self._spice_row.set_subtitle(
                "Localhost: virt-viewer connects from this host only. "
                "All interfaces: accessible over the network."
            )
            spice_model = Gtk.StringList()
            for lbl in _SPICE_LABELS:
                spice_model.append(lbl)
            self._spice_row.set_model(spice_model)
            current_spice = cfg.get("spice_listen", "127.0.0.1")
            try:
                spice_idx = _SPICE_ADDRESSES.index(current_spice)
            except ValueError:
                spice_idx = 0
            self._spice_row.set_selected(spice_idx)
            self._display_group.add(self._spice_row)
        else:
            # No SPICE device — offer to add one
            self._spice_row = None
            no_spice_row = Adw.ActionRow()
            no_spice_row.set_title("No display device")
            no_spice_row.set_subtitle(
                "This VM has no SPICE graphics device (headless). "
                "Add one to enable virt-viewer console access."
            )
            add_spice_btn = Gtk.Button(label="Add SPICE")
            add_spice_btn.set_valign(Gtk.Align.CENTER)
            add_spice_btn.add_css_class("suggested-action")
            add_spice_btn.connect("clicked", self._on_add_spice)
            no_spice_row.add_suffix(add_spice_btn)
            self._display_group.add(no_spice_row)

        # ── Boot ─────────────────────────────────────────────────────────
        boot_group = Adw.PreferencesGroup()
        boot_group.set_title("Boot")
        if self._running:
            boot_group.set_description("Change takes effect after next boot.")
        body.append(boot_group)

        self._boot_row = Adw.SwitchRow()
        self._boot_row.set_title("Boot from ISO first")
        self._boot_row.set_subtitle("Cdrom takes priority over the primary disk")
        self._boot_row.set_active(cfg.get("boot_iso_first", False))
        boot_group.add(self._boot_row)

        # ── Installation media ────────────────────────────────────────────
        iso_group = Adw.PreferencesGroup()
        iso_group.set_title("Installation media")
        if self._running:
            iso_group.set_description("Change takes effect after next boot.")
        else:
            iso_group.set_description("Leave blank to eject the current disc.")
        body.append(iso_group)

        self._iso_row = Adw.EntryRow()
        self._iso_row.set_title("ISO path")
        self._iso_row.set_text(cfg.get("iso_path", ""))

        iso_browse = _make_file_chooser_button(
            parent_widget=self,
            entry=self._iso_row,
            title="Select ISO image",
            filters=[("ISO images", ["*.iso"]), ("All files", ["*"])],
            initial_folder="/home",
        )
        self._iso_row.add_suffix(iso_browse)

        clear_btn = Gtk.Button()
        clear_btn.set_icon_name("edit-clear-symbolic")
        clear_btn.set_tooltip_text("Eject ISO")
        clear_btn.set_valign(Gtk.Align.CENTER)
        clear_btn.add_css_class("flat")
        clear_btn.connect("clicked", lambda _: self._iso_row.set_text(""))
        self._iso_row.add_suffix(clear_btn)
        iso_group.add(self._iso_row)

    # ------------------------------------------------------------------ #
    # Add SPICE device                                                     #
    # ------------------------------------------------------------------ #

    def _on_add_spice(self, _btn):
        """Inject a minimal SPICE graphics device into the domain XML."""
        import xml.etree.ElementTree as ET
        xml = self._mgr.get_domain_xml_pretty(self._info.name)
        if not xml:
            self._show_banner("Could not load domain XML.", error=True)
            return
        try:
            root = ET.fromstring(xml)
            devices = root.find("devices")
            if devices is None:
                self._show_banner("No <devices> element in domain XML.", error=True)
                return

            # Build SPICE graphics element
            gfx = ET.SubElement(devices, "graphics")
            gfx.set("type", "spice")
            gfx.set("autoport", "yes")
            listen = ET.SubElement(gfx, "listen")
            listen.set("type", "address")
            listen.set("address", "127.0.0.1")
            img = ET.SubElement(gfx, "image")
            img.set("compression", "off")

            # Add virtio video if no video device present
            if devices.find("video") is None:
                video = ET.SubElement(devices, "video")
                model = ET.SubElement(video, "model")
                model.set("type", "virtio")
                model.set("heads", "1")
                model.set("primary", "yes")

            # Add SPICE agent channel
            ch = ET.SubElement(devices, "channel")
            ch.set("type", "spicevmc")
            tgt = ET.SubElement(ch, "target")
            tgt.set("type", "virtio")
            tgt.set("name", "com.redhat.spice.0")

            new_xml = ET.tostring(root, encoding="unicode")
            ok, msg = self._mgr.apply_domain_xml(self._info.name, new_xml)
            if ok:
                self._show_banner("SPICE device added. Reopen Configure to set listen address.", error=False)
            else:
                self._show_banner(msg, error=True)
        except ET.ParseError as e:
            self._show_banner(f"XML parse error: {e}", error=True)

    # ------------------------------------------------------------------ #
    # Apply                                                                #
    # ------------------------------------------------------------------ #

    def _on_apply(self, _btn):
        name     = self._info.name
        errors: list[str]   = []
        successes: list[str] = []

        def run(ok, msg):
            (successes if ok else errors).append(msg)

        # vCPUs and memory — only when stopped (methods guard themselves)
        if not self._running:
            run(*self._mgr.set_vcpus(name, int(self._vcpu_row.get_value())))
            run(*self._mgr.set_memory(name, int(self._mem_row.get_value())))

        # Network — collect all interface changes into one call
        net_updates: list[tuple[int, str]] = []
        for iface_idx, combo, options in self._net_combos:
            sel = combo.get_selected()
            if 0 <= sel < len(options):
                net_updates.append((iface_idx, options[sel]))
        if net_updates:
            run(*self._mgr.set_networks(name, net_updates))

        if self._spice_row is not None:
            spice_idx = self._spice_row.get_selected()
            if spice_idx < len(_SPICE_ADDRESSES):
                run(*self._mgr.set_spice_listen(name, _SPICE_ADDRESSES[spice_idx]))

        run(*self._mgr.set_boot_order(name, self._boot_row.get_active()))

        iso_path = self._iso_row.get_text().strip() or None
        run(*self._mgr.set_iso(name, iso_path))

        # Filter out the "skipped" non-error successes from the count
        real_errors = [e for e in errors if e]
        if real_errors:
            self._show_banner("Errors: " + "; ".join(real_errors), error=True)
        else:
            n = len([s for s in successes if "skipped" not in s.lower()])
            self._show_banner(
                f"Applied {n} change(s) successfully."
                + (" Reboot VM for changes to take effect." if self._running else ""),
                error=False,
            )

    # ------------------------------------------------------------------ #
    # Banner helper                                                         #
    # ------------------------------------------------------------------ #

    def _show_banner(self, message: str, error: bool):
        self._banner.set_title(message)
        self._banner.set_revealed(True)
        if not error:
            GLib.timeout_add_seconds(5, lambda: self._banner.set_revealed(False) or False)
